import{_ as i,I as d,c as r,o,j as t,ap as s,a as e,J as n}from"./chunks/framework.BVMg0REN.js";const x=JSON.parse('{"title":"实例与任务列表","description":"","frontmatter":{},"headers":[],"relativePath":"Features/InstancesAndTaskList.md","filePath":"zh/Features/InstancesAndTaskList.md","lastUpdated":1779514879000}'),c={name:"Features/InstancesAndTaskList.md"},h={id:"实例与任务列表",tabindex:"-1"};function b(m,a,u,p,k,f){const l=d("Badge");return o(),r("div",null,[t("h1",h,[a[0]||(a[0]=e("实例与任务列表")),n(l,{type:"warning",text:"普通"}),a[1]||(a[1]=e()),a[2]||(a[2]=t("a",{class:"header-anchor",href:"#实例与任务列表","aria-label":"Permalink to “实例与任务列表”"},"​",-1))]),a[3]||(a[3]=s('<div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>本文对应参考文档中的“实例管理”和“任务列表”说明，适合刚开始整理自己的预设时查阅。</p></div><h2 id="一、实例管理" tabindex="-1">一、实例管理 <a class="header-anchor" href="#一、实例管理" aria-label="Permalink to “一、实例管理”">​</a></h2><h3 id="新建与切换" tabindex="-1">新建与切换 <a class="header-anchor" href="#新建与切换" aria-label="Permalink to “新建与切换”">​</a></h3><ul><li>在界面最上方操作。</li><li>点击即可切换当前实例。</li></ul><h3 id="右键实例可做的事" tabindex="-1">右键实例可做的事 <a class="header-anchor" href="#右键实例可做的事" aria-label="Permalink to “右键实例可做的事”">​</a></h3><ul><li>复制</li><li>导出配置</li><li>导入配置</li><li>重命名</li></ul><h2 id="二、任务列表常用操作" tabindex="-1">二、任务列表常用操作 <a class="header-anchor" href="#二、任务列表常用操作" aria-label="Permalink to “二、任务列表常用操作”">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>全选 / 全不选</td><td>一键勾选或取消所有任务</td></tr><tr><td>添加任务</td><td>预置任务不足时手动补充，也可查找目标任务</td></tr><tr><td>重置任务</td><td>恢复为内置预设，会覆盖当前预设内容</td></tr><tr><td>修改任务名</td><td>在任务名旁空白处右键</td></tr><tr><td>单独运行 / 从此处运行</td><td>便于局部调试任务流程</td></tr><tr><td>删除任务</td><td>直接从当前实例移除</td></tr><tr><td>跳过任务</td><td>右键任务名后，当前轮运行会跳过该任务</td></tr><tr><td>任务排序</td><td>拖动任务即可调整顺序</td></tr></tbody></table><h2 id="三、任务列表的使用建议" tabindex="-1">三、任务列表的使用建议 <a class="header-anchor" href="#三、任务列表的使用建议" aria-label="Permalink to “三、任务列表的使用建议”">​</a></h2><ol><li>日常任务适合每次运行执行一次。</li><li>需要持续刷取的内容，优先使用特色功能或循环任务。</li><li>改动较多时，先复制实例再试，不要直接在主用实例上大改。</li></ol><h2 id="四、多开与总控台" tabindex="-1">四、多开与总控台 <a class="header-anchor" href="#四、多开与总控台" aria-label="Permalink to “四、多开与总控台”">​</a></h2><p><code>V2.1.0</code> 之后支持 <code>1VN</code> 个模拟器，旧版本通常需要复制多个本体做 <code>1V1</code> 操作。</p><h3 id="多开基础要求" tabindex="-1">多开基础要求 <a class="header-anchor" href="#多开基础要求" aria-label="Permalink to “多开基础要求”">​</a></h3><ul><li>电脑性能要足够</li><li>需要了解基础 <code>ADB</code> 使用</li><li>模拟器本身要支持多开</li><li>建议善用搜索与本手册排查端口问题</li></ul><h3 id="创建新实例并连接" tabindex="-1">创建新实例并连接 <a class="header-anchor" href="#创建新实例并连接" aria-label="Permalink to “创建新实例并连接”">​</a></h3><ol><li>点击主页右上角 <code>+</code> 新建实例。</li><li>点击连接框的 <code>🔄</code> 刷新按钮自动检测端口。</li><li>或点击“自定义”手动填写 <code>ADB</code> 路径和地址。</li><li>打开“记住连接”，让实例记住当前模拟器。</li></ol><h3 id="总控台说明" tabindex="-1">总控台说明 <a class="header-anchor" href="#总控台说明" aria-label="Permalink to “总控台说明”">​</a></h3><ul><li>入口在左侧边栏。</li><li>可查看各实例实时画面与连接状态。</li><li>支持启动 / 停止任务。</li><li>总控台偏监控和控制用途，新建或编辑连接仍在主界面完成。</li></ul><h2 id="五、启动配置" tabindex="-1">五、启动配置 <a class="header-anchor" href="#五、启动配置" aria-label="Permalink to “五、启动配置”">​</a></h2><p>如果需要自动启动模拟器：</p><ol><li>打开“启动后操作 → 启动模拟器并开始任务”。</li><li>在“设置 → 启动设置”填写模拟器路径和附加命令。</li><li>多开号参数可通过快捷方式目标栏或任务管理器命令行查看。</li></ol><details class="details custom-block"><summary>启动参数示例</summary><ul><li>MuMu 常见参数形如 <code>-v 0</code></li><li>BlueStacks 常见参数形如 <code>--instance Nougat32</code></li></ul></details>',22))])}const P=i(c,[["render",b]]);export{x as __pageData,P as default};
